    mul   \Z2, \A2, \BI
    mul   \Z3, \A3, \BI
    mul   \Z4, \A4, \BI
    mul   \Z5, \A5, \BI
    umulh \T0, \A0, \BI
    adds  \Z1, \Z1, \T0
    umulh \T0, \A1, \BI
    adcs  \Z2, \Z2, \T0
    umulh \T0, \A2, \BI
    adcs  \Z3, \Z3, \T0
    umulh \T0, \A3, \BI
    adcs  \Z4, \Z4, \T0
    umulh \T0, \A4, \BI
    adcs  \Z5, \Z5, \T0
    umulh \Z6, \A5, \BI
    adc   \Z6, \Z6, xzr
.endm

