    ldr   \BI, [\M0, #8]
    MULADD64x384  \Z1,\Z2,\Z3,\Z4,\Z5,\Z6,\Z0, \A0,\A1,\A2,\A3,\A4,\A5, \BI, \T0
    // [Z2:Z6, Z0] <- z = (z0 x p_plus_1 + z)/2^64
    MULADD64x64 \Z1,\Z2,\Z3,\Z4,\Z5,\Z6,\Z0, \T0, \BI

    // [Z2:Z6, Z0:Z1] <- z = a x b2 + z
    mov   \Z1, xzr
    ldr   \BI, [\M0, #16]
    MULADD64x384  \Z2,\Z3,\Z4,\Z5,\Z6,\Z0,\Z1, \A0,\A1,\A2,\A3,\A4,\A5, \BI, \T0
    // [Z3:Z6, Z0:Z1] <- z = (z0 x p_plus_1 + z)/2^64
    MULADD64x64 \Z2,\Z3,\Z4,\Z5,\Z6,\Z0,\Z1, \T0, \BI

    // [Z3:Z6, Z0:Z2] <- z = a x b3 + z
    mov   \Z2, xzr
    ldr   \BI, [\M0, #24]
    MULADD64x384  \Z3,\Z4,\Z5,\Z6,\Z0,\Z1,\Z2, \A0,\A1,\A2,\A3,\A4,\A5, \BI, \T0
    // [Z4:Z6, Z0:Z2] <- z = (z0 x p_plus_1 + z)/2^64
    MULADD64x64 \Z3,\Z4,\Z5,\Z6,\Z0,\Z1,\Z2, \T0, \BI

    // [Z4:Z6, Z0:Z3] <- z = a x b4 + z
    mov   \Z3, xzr
    ldr   \BI, [\M0, #32]
    MULADD64x384  \Z4,\Z5,\Z6,\Z0,\Z1,\Z2,\Z3, \A0,\A1,\A2,\A3,\A4,\A5, \BI, \T0
    // [Z5:Z6, Z0:Z3] <- z = (z0 x p_plus_1 + z)/2^64
    MULADD64x64 \Z4,\Z5,\Z6,\Z0,\Z1,\Z2,\Z3, \T0, \BI

    // [Z5:Z6, Z0:Z4] <- z = a x b5 + z
    mov   \Z4, xzr
    ldr   \BI, [\M0, #40]
    MULADD64x384  \Z5,\Z6,\Z0,\Z1,\Z2,\Z3,\Z4, \A0,\A1,\A2,\A3,\A4,\A5, \BI, \T0
