    and   x16, x16, x17
    adds  x15, x15, x17
    adcs  x9, x9, x17
    adcs  x10, x10, x17
    adcs  x11, x11, x17
    adcs  x12, x12, x17
    adc   x13, x13, x16
    stp   x15, x9, [x0]
    stp   x10, x11, [x0, #16]
    stp   x12, x13, [x0, #32]
