//          fully read: c may alias a or b)
//  Register allocation: multiplicand (r/b0/b1 in turn) = x3..x8;
//                       acc z0..z6 = x9..x15,
//                       scalar bi = x16, MULADD temp x17;
//                       scalars (s/a0/a1) streamed from [sp]/[x1].
//  Stack: [sp+0 .. 48) holds s = a0+a1, then P2;
//         [sp+48 .. 96) holds P0.
//***********************************************************************
.global CDECL(fp2_mul)
.p2align 6
CDECL(fp2_mul):
    sub   sp, sp, #96                // scratch for s/P2 + P0

    // s = a0 + a1 (unreduced, < 2p) -> [sp]
    ldp   x9, x10, [x1]
    ldp   x11, x12, [x1, #16]
    ldp   x13, x14, [x1, #32]
    ldp   x16, x17, [x1, #48]
    adds  x9, x9, x16
    adcs  x10, x10, x17
    ldp   x16, x17, [x1, #64]
    adcs  x11, x11, x16
    adcs  x12, x12, x17
    ldp   x16, x17, [x1, #80]
    adcs  x13, x13, x16
    adc   x14, x14, x17
    stp   x9, x10, [sp]
    stp   x11, x12, [sp, #16]
    stp   x13, x14, [sp, #32]
    // r = b0 + b1 (unreduced, < 2p) -> x3..x8
    ldp   x3, x4, [x2]
    ldp   x5, x6, [x2, #16]
    ldp   x7, x8, [x2, #32]
    ldp   x16, x17, [x2, #48]
    adds  x3, x3, x16
    adcs  x4, x4, x17
    ldp   x16, x17, [x2, #64]
    adcs  x5, x5, x16
    adcs  x6, x6, x17
    ldp   x16, x17, [x2, #80]
    adcs  x7, x7, x16
    adc   x8, x8, x17

    // P2 = r x s -> [sp], overwriting s
    // x9..x15 <- z = a x b0
    ldr   x16, [sp]
    MUL64x384  x9,x10,x11,x12,x13,x14,x15, x3,x4,x5,x6,x7,x8, x16, x17
    FPMUL384x384  sp, x3,x4,x5,x6,x7,x8, x9,x10,x11,x12,x13,x14,x15, x16, x17
    // reduce x15,x9..x13 into [0, p)
    mov   x16, #-1
    movn  x17, #0xe2c0, lsl #48      // p[5] = 0x1D3FFFFFFFFFFFFF
    subs  x15, x15, x16
    sbcs  x9, x9, x16
    sbcs  x10, x10, x16
    sbcs  x11, x11, x16
    sbcs  x12, x12, x16
    sbcs  x13, x13, x17
    sbc   x16, xzr, xzr              // mask = -borrow
    and   x17, x17, x16
    adds  x15, x15, x16
    adcs  x9, x9, x16
    adcs  x10, x10, x16
    adcs  x11, x11, x16
    adcs  x12, x12, x16
    adc   x13, x13, x17
    stp   x15, x9, [sp]
    stp   x10, x11, [sp, #16]
    stp   x12, x13, [sp, #32]

    // P0 = b0 x a0 -> [sp+48]
    ldp   x3, x4, [x2]
    ldp   x5, x6, [x2, #16]
    ldp   x7, x8, [x2, #32]
    // x15,x9..x14 <- z = a x b0
    ldr   x16, [x1]
    MUL64x384  x15,x9,x10,x11,x12,x13,x14, x3,x4,x5,x6,x7,x8, x16, x17
    FPMUL384x384  x1, x3,x4,x5,x6,x7,x8, x15,x9,x10,x11,x12,x13,x14, x16, x17
    // reduce x14,x15,x9..x12 into [0, p)
    mov   x16, #-1
    movn  x17, #0xe2c0, lsl #48      // p[5] = 0x1D3FFFFFFFFFFFFF
    subs  x14, x14, x16
    sbcs  x15, x15, x16
    sbcs  x9, x9, x16
    sbcs  x10, x10, x16
    sbcs  x11, x11, x16
    sbcs  x12, x12, x17
    sbc   x16, xzr, xzr              // mask = -borrow
    and   x17, x17, x16
    adds  x14, x14, x16
    adcs  x15, x15, x16
    adcs  x9, x9, x16
    adcs  x10, x10, x16
    adcs  x11, x11, x16
    adc   x12, x12, x17
    stp   x14, x15, [sp, #48]
    stp   x9, x10, [sp, #64]
    stp   x11, x12, [sp, #80]

    // P1 = b1 x a1 -> x14,x15,x9..x12
    ldp   x3, x4, [x2, #48]
    ldp   x5, x6, [x2, #64]
    ldp   x7, x8, [x2, #80]
    add   x1, x1, #48                // a1; a and b are dead after P1
    // x14,x15,x9..x13 <- z = a x b0
    ldr   x16, [x1]
    MUL64x384  x14,x15,x9,x10,x11,x12,x13, x3,x4,x5,x6,x7,x8, x16, x17
    FPMUL384x384  x1, x3,x4,x5,x6,x7,x8, x14,x15,x9,x10,x11,x12,x13, x16, x17
    // reduce x13..x15,x9..x11 into [0, p)
    mov   x16, #-1
    movn  x17, #0xe2c0, lsl #48      // p[5] = 0x1D3FFFFFFFFFFFFF
    subs  x13, x13, x16
    sbcs  x14, x14, x16
    sbcs  x15, x15, x16
    sbcs  x9, x9, x16
    sbcs  x10, x10, x16
    sbcs  x11, x11, x17
    sbc   x16, xzr, xzr              // mask = -borrow
    and   x17, x17, x16
    adds  x13, x13, x16
    adcs  x14, x14, x16
    adcs  x15, x15, x16
    adcs  x9, x9, x16
    adcs  x10, x10, x16
    adc   x11, x11, x17

    // c0 = P0 - P1 -> x3..x8
    ldp   x3, x4, [sp, #48]
    ldp   x5, x6, [sp, #64]
    ldp   x7, x8, [sp, #80]
    movn  x17, #0xe2c0, lsl #48      // p[5] = 0x1D3FFFFFFFFFFFFF
    subs  x3, x3, x13
    sbcs  x4, x4, x14
    sbcs  x5, x5, x15
    sbcs  x6, x6, x9
    sbcs  x7, x7, x10
    sbcs  x8, x8, x11
    sbc   x16, xzr, xzr              // mask = -borrow
    and   x17, x17, x16
    adds  x3, x3, x16
    adcs  x4, x4, x16
    adcs  x5, x5, x16
    adcs  x6, x6, x16
    adcs  x7, x7, x16
    adc   x8, x8, x17
    stp   x3, x4, [x0]
    stp   x5, x6, [x0, #16]
    stp   x7, x8, [x0, #32]

    // c1 = (P2 - P1) - P0
    ldp   x3, x4, [sp]
    ldp   x5, x6, [sp, #16]
    ldp   x7, x8, [sp, #32]
    movn  x17, #0xe2c0, lsl #48      // p[5] = 0x1D3FFFFFFFFFFFFF
    subs  x3, x3, x13
    sbcs  x4, x4, x14
    sbcs  x5, x5, x15
    sbcs  x6, x6, x9
    sbcs  x7, x7, x10
    sbcs  x8, x8, x11
    sbc   x16, xzr, xzr              // mask = -borrow
    and   x17, x17, x16
    adds  x3, x3, x16
    adcs  x4, x4, x16
    adcs  x5, x5, x16
    adcs  x6, x6, x16
    adcs  x7, x7, x16
    adc   x8, x8, x17
    ldp   x13, x14, [sp, #48]
    ldp   x15, x9, [sp, #64]
    ldp   x10, x11, [sp, #80]
    movn  x17, #0xe2c0, lsl #48      // p[5] = 0x1D3FFFFFFFFFFFFF
    subs  x3, x3, x13
    sbcs  x4, x4, x14
    sbcs  x5, x5, x15
    sbcs  x6, x6, x9
    sbcs  x7, x7, x10
    sbcs  x8, x8, x11
    sbc   x16, xzr, xzr              // mask = -borrow
    and   x17, x17, x16
    adds  x3, x3, x16
    adcs  x4, x4, x16
    adcs  x5, x5, x16
    adcs  x6, x6, x16
    adcs  x7, x7, x16
    adc   x8, x8, x17
    stp   x3, x4, [x0, #48]
    stp   x5, x6, [x0, #64]
    stp   x7, x8, [x0, #80]
    add   sp, sp, #96
    ret

//***********************************************************************
//  Squaring in GF(p^2)
//  Operation: c0 = (a0+a1) x (a0-a1) ; c1 = 2 a0 x a1
//    with a0+a1, a0-a1+p and 2*a0 kept unreduced (< 2p), so both
//    Montgomery products are < 2p before their final reduction.
//  Inputs: a = [a0, a1] stored in [x1]
//  Output: c = [c0, c1] stored in [x0]  (c may alias a)
//  Register allocation: multiplicand (d = a0-a1+p, then a1) = x3..x8;
//                       acc z0..z6 = x9..x15,
//                       scalar bi = x16, MULADD temp x17;
//                       scalars streamed from [sp].
//  Stack: [sp+0 .. 48) holds s = a0+a1;
//         [sp+48 .. 96) holds t = 2*a0.
//***********************************************************************
.global CDECL(fp2_sqr)
.p2align 6
CDECL(fp2_sqr):
    sub   sp, sp, #96                // scratch for s + t

    // t = 2*a0 (unreduced) -> [sp+48] ; a0 stays in x3..x8
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    adds  x9, x3, x3
    adcs  x10, x4, x4
    adcs  x11, x5, x5
    adcs  x12, x6, x6
    adcs  x13, x7, x7
    adc   x14, x8, x8
    stp   x9, x10, [sp, #48]
    stp   x11, x12, [sp, #64]
    stp   x13, x14, [sp, #80]
    // s = a0 + a1 (unreduced) -> [sp]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldp   x13, x14, [x1, #80]
    adds  x9, x9, x3
    adcs  x10, x10, x4
    adcs  x11, x11, x5
    adcs  x12, x12, x6
    adcs  x13, x13, x7
    adc   x14, x14, x8
    stp   x9, x10, [sp]
    stp   x11, x12, [sp, #16]
    stp   x13, x14, [sp, #32]
    // d = a0 - a1 + p (unreduced, in (0, 2p)) -> x3..x8
    ldp   x9, x10, [x1, #48]
    subs  x3, x3, x9
    sbcs  x4, x4, x10
    ldp   x9, x10, [x1, #64]
    sbcs  x5, x5, x9
    sbcs  x6, x6, x10
    ldp   x9, x10, [x1, #80]
    sbcs  x7, x7, x9
    sbcs  x8, x8, x10
    mov   x9, #-1
    movn  x10, #0xe2c0, lsl #48      // p[5] = 0x1D3FFFFFFFFFFFFF
    adds  x3, x3, x9
    adcs  x4, x4, x9
    adcs  x5, x5, x9
    adcs  x6, x6, x9
    adcs  x7, x7, x9
    adc   x8, x8, x10

    // c0 = d x s -> [out] (a0's slot; a1 is still intact if c == a)
    // x9..x15 <- z = a x b0
    ldr   x16, [sp]
    MUL64x384  x9,x10,x11,x12,x13,x14,x15, x3,x4,x5,x6,x7,x8, x16, x17
    FPMUL384x384  sp, x3,x4,x5,x6,x7,x8, x9,x10,x11,x12,x13,x14,x15, x16, x17
    // reduce x15,x9..x13 into [0, p)
    mov   x16, #-1
    movn  x17, #0xe2c0, lsl #48      // p[5] = 0x1D3FFFFFFFFFFFFF
    subs  x15, x15, x16
    sbcs  x9, x9, x16
    sbcs  x10, x10, x16
    sbcs  x11, x11, x16
    sbcs  x12, x12, x16
    sbcs  x13, x13, x17
    sbc   x16, xzr, xzr              // mask = -borrow
    and   x17, x17, x16
    adds  x15, x15, x16
    adcs  x9, x9, x16
    adcs  x10, x10, x16
    adcs  x11, x11, x16
    adcs  x12, x12, x16
    adc   x13, x13, x17
    stp   x15, x9, [x0]
    stp   x10, x11, [x0, #16]
    stp   x12, x13, [x0, #32]

    // c1 = a1 x t -> [out+48]
    ldp   x3, x4, [x1, #48]
    ldp   x5, x6, [x1, #64]
    ldp   x7, x8, [x1, #80]
    add   x1, sp, #48                // x1 is dead after the a1 load: reuse it as the t pointer
    // x15,x9..x14 <- z = a x b0
    ldr   x16, [x1]
    MUL64x384  x15,x9,x10,x11,x12,x13,x14, x3,x4,x5,x6,x7,x8, x16, x17
    FPMUL384x384  x1, x3,x4,x5,x6,x7,x8, x15,x9,x10,x11,x12,x13,x14, x16, x17
    // reduce x14,x15,x9..x12 into [0, p)
    mov   x16, #-1
    movn  x17, #0xe2c0, lsl #48      // p[5] = 0x1D3FFFFFFFFFFFFF
    subs  x14, x14, x16
    sbcs  x15, x15, x16
    sbcs  x9, x9, x16
    sbcs  x10, x10, x16
    sbcs  x11, x11, x16
    sbcs  x12, x12, x17
    sbc   x16, xzr, xzr              // mask = -borrow
    and   x17, x17, x16
    adds  x14, x14, x16
    adcs  x15, x15, x16
    adcs  x9, x9, x16
    adcs  x10, x10, x16
    adcs  x11, x11, x16
    adc   x12, x12, x17
    stp   x14, x15, [x0, #48]
    stp   x9, x10, [x0, #64]
    stp   x11, x12, [x0, #80]
    add   sp, sp, #96
    ret
